targets.query:
from(bucket: "threads")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "loadtest_summary")
  // Гарантируем по одной записи на поле для каждого run_id
  |> group(columns:["run_id","test_case","target_rps","duration_s","_field"]) 
  |> last()
  |> pivot(rowKey:["_time","run_id","test_case","target_rps","duration_s"], columnKey:["_field"], valueColumn:"_value")
  // Снимаем group key, иначе Grafana трактует run_id/test_case как labels и схлопывает строки
  |> group()
  // Переименовываем время
  |> rename(columns: {_time: "date"})
  // Алиас test_case: 1=server, 2=client, 3=dynamic
  |> map(fn: (r) => ({ r with test_case_label: if r.test_case == "1" then "server" else if r.test_case == "2" then "client" else if r.test_case == "3" then "dynamic" else r.test_case }))
  |> keep(columns:["date","run_id","test_case","test_case_label","target_rps","duration_s","vus_count","p95_ms","avg_ms","median_ms","throughput_rps","client_share","redirected_ok_count","sent_count","completed_count","ok_count","error_count","network_error_count","wall_clock_s","tail_s"])
  |> sort(columns:["date"], desc:true)
